"""List/emit hunks of `git diff -U0` for a path, renumbering the new side so a
subset of hunks forms a self-consistent patch that applies in one go."""
import re, subprocess, sys

HDR = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(.*)$")

def load(path):
    text = subprocess.run(["git","diff","-U0","--",path],capture_output=True,text=True).stdout
    head, hunks, cur = [], [], None
    for ln in text.splitlines(keepends=True):
        if ln.startswith("@@"):
            if cur: hunks.append(cur)
            cur = [ln]
        elif cur is not None: cur.append(ln)
        else: head.append(ln)
    if cur: hunks.append(cur)
    return head, hunks

def parse(h):
    m = HDR.match(h[0].rstrip("\n"))
    os_, oc, ns, nc, tail = m.group(1), m.group(2), m.group(3), m.group(4), m.group(5)
    return int(os_), 1 if oc is None else int(oc), int(ns), 1 if nc is None else int(nc), tail

mode, path = sys.argv[1], sys.argv[2]
head, hunks = load(path)
if mode == "list":
    for i,h in enumerate(hunks):
        body=[l.rstrip()[:120] for l in h[1:]]
        print(f"### {i} {h[0].rstrip()}")
        for l in body[:4]: print("   ",l)
        if len(body)>4: print(f"    ...(+{len(body)-4})")
else:
