        oldpart = f"-{os_}" if oc == 1 else f"-{os_},{oc}"
        newpart = f"+{ns2}" if nc == 1 else f"+{ns2},{nc}"
        out.append(f"@@ {oldpart} {newpart} @@{tail}\n")
        out.extend(h[1:])
        delta += nc - oc
    sys.stdout.write("".join(out))
